import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.DB9Ll7VW.js";const h=JSON.parse('{"title":"Learners, instructors & enrollments","description":"Manage students, instructors, and assistants — plus the People hub, enrollment list, manual enroll, instructor approvals, certificates, and the learner account.","frontmatter":{"title":"Learners, instructors & enrollments","description":"Manage students, instructors, and assistants — plus the People hub, enrollment list, manual enroll, instructor approvals, certificates, and the learner account."},"headers":[],"relativePath":"learners.md","filePath":"learners.md","lastUpdated":1778327862000}'),n={name:"learners.md"};function o(i,e,l,d,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="learners-instructors-enrollments" tabindex="-1">Learners, instructors &amp; enrollments <a class="header-anchor" href="#learners-instructors-enrollments" aria-label="Permalink to &quot;Learners, instructors &amp; enrollments&quot;">​</a></h1><p>Sikshya keeps four kinds of users in mind:</p><ul><li><strong>Administrators</strong> — run the academy.</li><li><strong>Instructors</strong> — build and teach courses.</li><li><strong>Assistants</strong> — help with grading, support, and reports (no full admin power).</li><li><strong>Students</strong> — the learners.</li></ul><p>This page is the practical &quot;where do I click to manage these people&quot; guide.</p><h2 id="the-people-hub" tabindex="-1">The People hub <a class="header-anchor" href="#the-people-hub" aria-label="Permalink to &quot;The People hub&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → People → Students &amp; Instructors</span>.</p><p>You&#39;ll see three tabs:</p><ul><li><strong>Students</strong> — every learner account.</li><li><strong>Instructors</strong> — every instructor account.</li><li><strong>Applications</strong> — pending instructor applications (people who want to teach).</li></ul><p>Each tab uses the same list layout: <strong>Search</strong>, <strong>Sort</strong>, <strong>Bulk actions</strong>, paginated rows.</p><h3 id="students-tab" tabindex="-1">Students tab <a class="header-anchor" href="#students-tab" aria-label="Permalink to &quot;Students tab&quot;">​</a></h3><p>Columns: avatar, name, email, courses enrolled, last activity, registered date.</p><p>Click any row to open the standard WordPress user profile page with extra Sikshya tabs (enrollments, attempts, certificates).</p><p>Bulk actions: send password reset, deactivate, delete (with the standard WordPress user-removal confirmations).</p><h3 id="instructors-tab" tabindex="-1">Instructors tab <a class="header-anchor" href="#instructors-tab" aria-label="Permalink to &quot;Instructors tab&quot;">​</a></h3><p>Same columns plus <strong>Courses authored</strong>.</p><p>You can promote any user to <strong>Sikshya Instructor</strong> by editing their WordPress profile and adding the role — but the cleaner path is the <strong>Applications</strong> workflow below.</p><h3 id="applications-tab" tabindex="-1">Applications tab <a class="header-anchor" href="#applications-tab" aria-label="Permalink to &quot;Applications tab&quot;">​</a></h3><p>When someone signs up as an instructor (via <code>[sikshya_registration type=&quot;instructor&quot;]</code> or by clicking &quot;Apply to teach&quot; in their account), they don&#39;t immediately get the instructor role. Instead, an <strong>application</strong> appears here.</p><p>For each application you&#39;ll see:</p><ul><li>Applicant name and email.</li><li>Their bio / why-they-want-to-teach text.</li><li><strong>Approve</strong> button → grants the <code>sikshya_instructor</code> role and they can now create courses.</li><li><strong>Reject</strong> button → declines (you can write a short note).</li></ul><div class="ui-tip"><strong>Why two-step approval?</strong> Approving manually is intentional friction — it stops random sign-ups from appearing as authors on your site. If you trust everyone, automate it with a small custom plugin (see <a href="/hooks-filters#authentication-instructor-lifecycle">hooks reference</a>).</div><h2 id="enrollments" tabindex="-1">Enrollments <a class="header-anchor" href="#enrollments" aria-label="Permalink to &quot;Enrollments&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → People → Enrollments</span>.</p><p>This is the master list of every &quot;this learner is in this course&quot; record on your site.</p><p>You&#39;ll see:</p><ul><li><strong>Search</strong> by learner name, email, or course title.</li><li><strong>Status filter</strong> — Enrolled, Completed, Refunded, Cancelled.</li><li>A table with columns: Learner, Course, Enrolled date, Status, Progress, Source (Free / Paid / Manual / Coupon).</li><li>A <strong>Manual enroll</strong> panel at the top of the page.</li></ul><h3 id="manual-enroll" tabindex="-1">Manual enroll <a class="header-anchor" href="#manual-enroll" aria-label="Permalink to &quot;Manual enroll&quot;">​</a></h3><p>Use this when you give someone a course outside the normal flow — comp accounts, gifts, B2B sales done over invoice.</p><ol class="step-list"><li>Type the learner&#39;s name in the <strong>Student</strong> autocomplete (it searches existing users).</li><li>Pick the <strong>Course</strong> from the autocomplete.</li><li>Click <strong>Enroll {student}</strong>. The button shows &quot;Enrolling…&quot; until done.</li></ol><p>The enrollment row is created instantly. The learner gets the standard enrollment email (unless you disable it in <span class="screen-path">Settings → Email</span>).</p><h2 id="roles-capabilities" tabindex="-1">Roles &amp; capabilities <a class="header-anchor" href="#roles-capabilities" aria-label="Permalink to &quot;Roles &amp; capabilities&quot;">​</a></h2><p>Sikshya creates three custom WordPress roles, each with sensible defaults:</p><table tabindex="0"><thead><tr><th>Role</th><th>What they can do</th></tr></thead><tbody><tr><td><strong>Sikshya Instructor</strong></td><td>Build courses, lessons, quizzes, assignments. Edit their own content, view their own course reports.</td></tr><tr><td><strong>Sikshya Student</strong></td><td>Enroll, learn, take quizzes, submit assignments, view certificates.</td></tr><tr><td><strong>Sikshya Assistant</strong></td><td>Editor-style support staff. Grade assignments, view reports, but can&#39;t publish courses.</td></tr><tr><td><strong>Administrator</strong></td><td>Full Sikshya control (default WordPress admin capabilities + every Sikshya capability).</td></tr></tbody></table><h3 id="capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Admin</th><th>Instructor</th><th>Assistant</th><th>Student</th></tr></thead><tbody><tr><td>Manage Sikshya (master switch)</td><td>✅</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Open the Sikshya admin app</td><td>✅</td><td>✅</td><td>✅</td><td>—</td></tr><tr><td>Edit own courses / lessons / quizzes</td><td>✅</td><td>✅</td><td>—</td><td>—</td></tr><tr><td>Publish a course</td><td>✅</td><td>✅</td><td>—</td><td>—</td></tr><tr><td>Manage students</td><td>✅</td><td>✅</td><td>✅</td><td>—</td></tr><tr><td>View reports</td><td>✅</td><td>✅</td><td>✅</td><td>—</td></tr><tr><td>Enroll on free courses</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Take quizzes</td><td>✅</td><td>—</td><td>—</td><td>✅</td></tr><tr><td>Submit assignments</td><td>✅</td><td>—</td><td>—</td><td>✅</td></tr><tr><td>View own certificates</td><td>✅</td><td>—</td><td>—</td><td>✅</td></tr></tbody></table><p>Use a role plugin like <strong>Members</strong> or <strong>User Role Editor</strong> to fine-tune individual capabilities without writing code.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multi-instructor &amp; revenue split</span></div><p class="pro-callout__desc">Assign multiple instructors per course (Owner / Editor / Grader roles) and split revenue automatically. Instructors get their own dashboard with earnings and payout requests.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock multi-instructor →</a></div><h2 id="quiz-attempts" tabindex="-1">Quiz attempts <a class="header-anchor" href="#quiz-attempts" aria-label="Permalink to &quot;Quiz attempts&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → People → Quiz attempts</span> (or under <strong>Reports</strong> depending on your version).</p><p>Each row is one attempt:</p><ul><li>Learner name and email.</li><li>Quiz title and parent course.</li><li>Score (with a pass / fail badge).</li><li>Time taken.</li><li>Submitted at.</li></ul><p>Click any row for a <strong>drilldown</strong> — the exact answers the learner gave, per question.</p><p>Bulk actions include <strong>Reset attempts</strong> (so a stuck learner can try again).</p><h2 id="assignment-grading" tabindex="-1">Assignment grading <a class="header-anchor" href="#assignment-grading" aria-label="Permalink to &quot;Assignment grading&quot;">​</a></h2><p>For assignments, open <span class="screen-path">Sikshya → Grading &amp; submissions → Assignment submissions</span> <span class="pro-pill">PRO</span>.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Gradebook &amp; assignment grading queue</span></div><p class="pro-callout__desc">Without Pro, you grade assignments one at a time from each lesson&#39;s editor. With <strong>Gradebook</strong> + <strong>Advanced assignments</strong> on, you get a unified queue with filters (ungraded, late, failed), rubric-based grading, restricted file types, and per-learner / per-course score export.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock the gradebook →</a></div><h2 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Certificates</span>. This hub has three tabs:</p><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p>The list of certificate <strong>designs</strong>. The free plugin ships <strong>Regalia</strong> (formal) and <strong>Vertex</strong> (modern, minimal).</p><p>Click <strong>+ Create</strong> to add a new template. The certificate editor opens full-screen — type a name, pick a paper size and orientation, and save. (For the visual builder with drag-and-drop placement, you need the <strong>Advanced certificates</strong> add-on — see below.)</p><h3 id="issued" tabindex="-1">Issued <a class="header-anchor" href="#issued" aria-label="Permalink to &quot;Issued&quot;">​</a></h3><p>Every certificate ever issued, in one list:</p><ul><li><strong>Search</strong> by learner or course.</li><li>Columns: Learner, Course, Issued date, Serial number, Status.</li><li>Row action: <strong>Revoke</strong> — opens a confirmation. Revoked certificates won&#39;t verify.</li></ul><h3 id="add-on-defaults-pro" tabindex="-1">Add-on defaults <span class="pro-pill">PRO</span> <a class="header-anchor" href="#add-on-defaults-pro" aria-label="Permalink to &quot;Add-on defaults &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h3><p>Visible only when <strong>Advanced certificates</strong> is on. Set defaults like QR placement, verification URL pattern, learner download options.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced certificates (drag-drop builder + QR verification)</span></div><p class="pro-callout__desc">Replace the basic presets with your own branded templates designed visually. Add merge fields (instructor name, score, serial number, completion date), and a <strong>QR code</strong> that links to a public verify page (<code>/certificate-verify?serial=...</code>) so anyone can confirm authenticity.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock advanced certificates →</a></div><h2 id="what-learners-actually-see" tabindex="-1">What learners actually see <a class="header-anchor" href="#what-learners-actually-see" aria-label="Permalink to &quot;What learners actually see&quot;">​</a></h2><p>The learner experience runs on three screens. Visit them in a private browser window after enrolling a test learner:</p><h3 id="_1-course-catalog-courses" tabindex="-1">1. Course catalog <code>/courses/</code> <a class="header-anchor" href="#_1-course-catalog-courses" aria-label="Permalink to &quot;1. Course catalog `/courses/`&quot;">​</a></h3><p>The public list of every published, non-hidden course. Filterable by category, tag, level, and price. Each card shows the title, image, instructor, level, length, and price.</p><h3 id="_2-single-course-page-course-slug" tabindex="-1">2. Single course page <code>/{course-slug}/</code> <a class="header-anchor" href="#_2-single-course-page-course-slug" aria-label="Permalink to &quot;2. Single course page `/{course-slug}/`&quot;">​</a></h3><p>Sections (in order): Hero (image, title, instructor, price, <strong>Enroll</strong> / <strong>Buy</strong> CTA), Description, Curriculum preview (with preview lessons playable inline), FAQ, Reviews <span class="pro-pill">PRO</span>, Instructor card, Related courses.</p><h3 id="_3-my-learning-my-learning" tabindex="-1">3. My learning <code>/my-learning/</code> <a class="header-anchor" href="#_3-my-learning-my-learning" aria-label="Permalink to &quot;3. My learning `/my-learning/`&quot;">​</a></h3><p>The signed-in learner&#39;s home. Sub-sections in the left rail:</p><ul><li><strong>My courses</strong> — every enrolled course with a progress bar and a <strong>Resume learning</strong> button.</li><li><strong>Wishlist</strong> — courses saved with the heart icon.</li><li><strong>Quiz attempts</strong> — every quiz the learner has taken, with scores.</li><li><strong>Certificates</strong> — issued certificates (download / verify link).</li><li><strong>Payments</strong> — order history, receipts, invoice PDFs.</li><li><strong>Profile</strong> — display name, email, password change.</li><li><strong>Apply to teach</strong> — instructor application form.</li></ul><h2 id="the-learn-hub-learn" tabindex="-1">The learn hub <code>/learn/</code> <a class="header-anchor" href="#the-learn-hub-learn" aria-label="Permalink to &quot;The learn hub `/learn/`&quot;">​</a></h2><p>Once enrolled, learners click into the actual lesson player at <code>/learn/</code>:</p><ul><li><strong>Curriculum sidebar</strong> on the left — chapters, lessons, quizzes, assignments. The current item is highlighted; locked items show a small lock icon.</li><li><strong>Lesson body</strong> in the middle — the text, video, or downloadable file.</li><li><strong>Mark complete</strong> button at the bottom — clicking this fires <code>sikshya_lesson_completed</code> and unlocks the next lesson.</li><li><strong>Next / previous</strong> navigation respects sequential progression (free) and any drip / prerequisite rules <span class="pro-pill">PRO</span>.</li></ul><p>When a learner completes the final lesson, the course is marked complete, a certificate issues automatically, and the <strong>Course completed</strong> + <strong>Certificate issued</strong> emails fire.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/docs/enrollment-settings">Enrollment &amp; access</a> — how learners get into courses.</li><li><a href="/docs/email-settings">Email &amp; notifications</a> — what we send them.</li><li><a href="/docs/third-party-integrations">Pro add-ons</a> — every Pro feature, with Buy CTA.</li></ul>',72)])])}const g=t(n,[["render",o]]);export{h as __pageData,g as default};
